# -*- coding: utf-8 -*-
"""Generate the locally-authored PDF/A + PDF/UA clause-conformance corpus.

GitHub #8 (Isartor-analogue), #14 (PDF/UA clause negatives), #7 (clause-sampled
conformance fixture set).

WHY THESE ARE AUTHORED HERE AND NOT DOWNLOADED
----------------------------------------------
The Isartor test suite and the veraPDF corpus are the obvious sources for
"one file per violated PDF/A clause".  Neither can be vendored:

  * The Isartor suite is distributed by the PDF Association under terms that do
    not permit redistribution inside another project's repository.
  * The veraPDF corpus is a ~2,900-file external download.  A test that fetches
    it at run time makes the suite depend on the network, and this project's
    fixtures are required to be committed and bounded.

`tests/fixtures/flaw_corpus/COVERAGE.md` §11 previously deferred this work with
a specific and correct objection:

    "F16 deliberately did NOT fabricate clause fixtures locally: a hand-made
     file asserting our own reading of a clause would be the same
     self-consistent oracle wearing a corpus's name."

THAT OBJECTION IS ANSWERED, NOT IGNORED, and the answer is the shape of this
generator rather than a promise in prose.  A hand-made fixture is a
self-consistent oracle when the SAME judgement decides both what the file
contains and what the validator should say about it.  Here the two are
separated:

  1. Every fixture is a **single-construct delta** from a control file that the
     validator accepts with ZERO errors.  The control is generated by the same
     code path, so the only difference between "accepted" and "rejected" is the
     one construct named in the fixture's file name.
  2. The clause each fixture targets is not asserted from a reading of ISO
     19005 -- it is asserted against the clause string PDFE's own validator
     source emits, which the C++ tests parse out of
     `src/compliance/PdfAValidator.cpp` and `ProhibitedFeatureScanner.cpp`
     rather than hard-coding.  A clause added to the product with no fixture
     here fails the coverage test.
  3. The controls are load-bearing negatives-of-the-negative: if the validator
     degenerated into "reject everything", every control would fail.

What this does NOT claim: it is not an independent reading of ISO 19005.  It
pins PDFE's validator against files whose single differing construct is stated
in the file name and in the manifest.  Genuine independence comes from veraPDF
via `tests/support/ConformanceChecker.cpp`, which is a separate mechanism.

DETERMINISM
-----------
Every byte is fixed: no timestamps, no random ids, no temp paths.  Re-running
this script over an unchanged tree must produce byte-identical files, which is
what lets the outputs be committed.

Usage:
    python tests/fixtures/gen_conformance_corpus.py            # write
    python tests/fixtures/gen_conformance_corpus.py --check    # verify only
"""
from __future__ import annotations

import argparse
import hashlib
import json
import pathlib
import struct
import sys
import zlib

REPO_FIXTURES = pathlib.Path(__file__).resolve().parent
OUT_DIR = REPO_FIXTURES / "flaw_corpus" / "conformance"

# ---------------------------------------------------------------------------
# Low-level PDF assembly
# ---------------------------------------------------------------------------

HEADER = b"%PDF-1.7\n%\xe2\xe3\xcf\xd3\n"

# Fixed document id.  A test fixture is not a secret and must be reproducible.
DOC_ID = bytes.fromhex("5044464520434f4e464f524d414e43452046")[:16]


def stream_obj(dict_body: bytes, data: bytes) -> bytes:
    """A stream object body with a correct /Length.  Never compressed: the
    point of these fixtures is that a human can read what they assert."""
    return (
        b"<<" + dict_body + b"/Length " + str(len(data)).encode() + b">>\n"
        b"stream\n" + data + b"\nendstream"
    )


def assemble(objects: list[bytes], trailer_extra: bytes = b"",
             header: bytes = HEADER) -> bytes:
    """Classic cross-reference TABLE (never an xref stream -- an xref stream
    implies object streams, which is itself one of the clauses under test)."""
    out = bytearray(header)
    offsets: list[int] = []
    for num, body in enumerate(objects, start=1):
        offsets.append(len(out))
        out += str(num).encode() + b" 0 obj\n" + body + b"\nendobj\n"

    xref_at = len(out)
    out += b"xref\n0 " + str(len(objects) + 1).encode() + b"\n"
    out += b"0000000000 65535 f \n"
    for off in offsets:
        out += ("%010d 00000 n \n" % off).encode()
    idhex = DOC_ID.hex().encode()
    out += (
        b"trailer\n<</Size " + str(len(objects) + 1).encode()
        + b"/Root 1 0 R" + trailer_extra
        + b"/ID[<" + idhex + b"><" + idhex + b">]>>\n"
        b"startxref\n" + str(xref_at).encode() + b"\n%%EOF\n"
    )
    return bytes(out)


# ---------------------------------------------------------------------------
# Building blocks shared by every fixture
# ---------------------------------------------------------------------------

def xmp_packet(part: str, conformance: str, ua_part: str | None = None) -> bytes:
    """A minimal XMP packet carrying pdfaid identification as ATTRIBUTES.

    `XmpMetadataWriter::detectPdfALevel` accepts either attributes or child
    elements; attributes are used here so the packet stays small and so the
    fixture does not merely echo the shape PDFE's own writer emits.
    """
    ua = b""
    if ua_part is not None:
        ua = (b' xmlns:pdfuaid="http://www.aiim.org/pdfua/ns/id/"'
              b' pdfuaid:part="' + ua_part.encode() + b'"')
    return (
        b'<?xpacket begin="" id="W5M0MpCehiHzreSzNTczkc9d"?>\n'
        b'<x:xmpmeta xmlns:x="adobe:ns:meta/">\n'
        b' <rdf:RDF xmlns:rdf="http://www.w3.org/1999/02/22-rdf-syntax-ns#">\n'
        b'  <rdf:Description rdf:about=""'
        b' xmlns:pdfaid="http://www.aiim.org/pdfa/ns/id/"'
        b' pdfaid:part="' + part.encode() + b'"'
        b' pdfaid:conformance="' + conformance.encode() + b'"' + ua + b'/>\n'
        b' </rdf:RDF>\n'
        b'</x:xmpmeta>\n'
        b'<?xpacket end="w"?>\n'
    )


# A 92-byte stand-in for an embedded font program.  `FontComplianceChecker`
# decides "embedded" on the PRESENCE of /FontFile2 in the descriptor and never
# parses it, and none of these fixtures is rendered -- only validated -- so a
# real TrueType blob would add 100 kB per fixture and prove nothing extra.
# Stated here rather than disguised: this is a placeholder, and any test that
# RENDERS these files would be testing the placeholder, not a font.
FONTFILE_STUB = (b"\x00\x01\x00\x00" + b"PDFE-CONFORMANCE-FONTFILE-PLACEHOLDER-"
                 b"NOT-A-REAL-TRUETYPE-PROGRAM\x00\x00")

TOUNICODE_CMAP = (
    b"/CIDInit /ProcSet findresource begin\n"
    b"12 dict begin\nbegincmap\n"
    b"/CMapName /PDFE-Conformance-ToUnicode def\n"
    b"/CMapType 2 def\n"
    b"1 begincodespacerange\n<20> <7E>\nendcodespacerange\n"
    b"1 beginbfrange\n<20> <7E> <0020>\nendbfrange\n"
    b"endcmap\nCMapName currentdict /CMap defineresource pop\nend\nend\n"
)

PAGE_CONTENT = b"BT /F1 12 Tf 72 720 Td (PDFE conformance fixture) Tj ET\n"

OUTPUT_INTENT = (
    b"<</Type/OutputIntent/S/GTS_PDFA1"
    b"/OutputConditionIdentifier(sRGB IEC61966-2.1)"
    b"/RegistryName(http://www.color.org)"
    b"/Info(sRGB IEC61966-2.1)>>"
)


def base_objects(*, part: str, conformance: str,
                 with_xmp: bool = True,
                 with_output_intent: bool = True,
                 embed_font: bool = True,
                 with_tounicode: bool = True,
                 tagged: bool = False,
                 catalog_extra: bytes = b"",
                 page_extra: bytes = b"",
                 ua_part: str | None = None) -> list[bytes]:
    """Object list for the family.  Object numbering is FIXED across every
    variant so that a diff between two fixtures shows only the intended delta.

      1 Catalog   2 Pages   3 Page   4 Contents   5 Font
      6 FontDescriptor   7 FontFile2   8 ToUnicode   9 Metadata (XMP)
      10 StructTreeRoot  11 Figure StructElem
    """
    catalog = b"<</Type/Catalog/Pages 2 0 R"
    if with_output_intent:
        catalog += b"/OutputIntents[" + OUTPUT_INTENT + b"]"
    if with_xmp:
        catalog += b"/Metadata 9 0 R"
    if tagged:
        catalog += b"/MarkInfo<</Marked true>>/StructTreeRoot 10 0 R"
    catalog += catalog_extra + b">>"

    font = (b"<</Type/Font/Subtype/TrueType/BaseFont/PDFEConformanceSans"
            b"/FirstChar 32/LastChar 126/Widths[" +
            b" ".join([b"500"] * 95) + b"]/Encoding/WinAnsiEncoding")
    if embed_font:
        font += b"/FontDescriptor 6 0 R"
    else:
        # A descriptor with NO /FontFile* is the "not embedded" shape: the
        # font is referenced by name and the reader must substitute.
        font += b"/FontDescriptor 6 0 R"
    if with_tounicode:
        font += b"/ToUnicode 8 0 R"
    font += b">>"

    descriptor = (b"<</Type/FontDescriptor/FontName/PDFEConformanceSans"
                  b"/Flags 32/FontBBox[0 -200 1000 900]/ItalicAngle 0"
                  b"/Ascent 900/Descent -200/CapHeight 700/StemV 80")
    if embed_font:
        descriptor += b"/FontFile2 7 0 R"
    descriptor += b">>"

    page = (b"<</Type/Page/Parent 2 0 R/MediaBox[0 0 612 792]"
            b"/Resources<</Font<</F1 5 0 R>>>>/Contents 4 0 R" + page_extra + b">>")

    objects = [
        catalog,
        b"<</Type/Pages/Kids[3 0 R]/Count 1>>",
        page,
        stream_obj(b"", PAGE_CONTENT),
        font,
        descriptor,
        stream_obj(b"/Length1 " + str(len(FONTFILE_STUB)).encode(), FONTFILE_STUB),
        stream_obj(b"", TOUNICODE_CMAP),
        stream_obj(b"/Type/Metadata/Subtype/XML",
                   xmp_packet(part, conformance, ua_part)),
    ]
    if tagged:
        objects.append(b"<</Type/StructTreeRoot/K[11 0 R]>>")
        objects.append(b"<</Type/StructElem/S/Document/P 10 0 R/K[]>>")
    return objects


# ---------------------------------------------------------------------------
# RC4 / standard security handler -- used only to BUILD the two deliberately
# encrypted fixtures (PDF/A clause 6.1.3, PDF/UA clause 7.16).
# ---------------------------------------------------------------------------

PAD = bytes.fromhex(
    "28BF4E5E4E758A4164004E56FFFA01082E2E00B6D0683E802F0CA9FE6453697A")
ENC_OWNER = b"owner"
ENC_USER = b""                 # empty user password -> opens with no prompt
ENC_PERMS = -4
ENC_KEY_BYTES = 16             # /Length 128, /V 2 /R 3


def rc4(key: bytes, data: bytes) -> bytes:
    s = list(range(256))
    j = 0
    for i in range(256):
        j = (j + s[i] + key[i % len(key)]) & 0xFF
        s[i], s[j] = s[j], s[i]
    out = bytearray()
    i = j = 0
    for byte in data:
        i = (i + 1) & 0xFF
        j = (j + s[i]) & 0xFF
        s[i], s[j] = s[j], s[i]
        out.append(byte ^ s[(s[i] + s[j]) & 0xFF])
    return bytes(out)


def _pad_pw(pw: bytes) -> bytes:
    return (pw + PAD)[:32]


def _owner_value() -> bytes:
    digest = hashlib.md5(_pad_pw(ENC_OWNER)).digest()
    for _ in range(50):
        digest = hashlib.md5(digest[:ENC_KEY_BYTES]).digest()
    key = digest[:ENC_KEY_BYTES]
    value = rc4(key, _pad_pw(ENC_USER))
    for i in range(1, 20):
        value = rc4(bytes(b ^ i for b in key), value)
    return value


def _file_key(o_value: bytes) -> bytes:
    md5 = hashlib.md5()
    md5.update(_pad_pw(ENC_USER))
    md5.update(o_value)
    md5.update(struct.pack("<i", ENC_PERMS))
    md5.update(DOC_ID)
    digest = md5.digest()
    for _ in range(50):
        digest = hashlib.md5(digest[:ENC_KEY_BYTES]).digest()
    return digest[:ENC_KEY_BYTES]


def _user_value(key: bytes) -> bytes:
    digest = hashlib.md5(PAD + DOC_ID).digest()
    value = rc4(key, digest)
    for i in range(1, 20):
        value = rc4(bytes(b ^ i for b in key), value)
    return value + b"\x00" * 16


def _object_key(file_key: bytes, num: int, gen: int) -> bytes:
    md5 = hashlib.md5()
    md5.update(file_key)
    md5.update(bytes([num & 0xFF, (num >> 8) & 0xFF, (num >> 16) & 0xFF]))
    md5.update(bytes([gen & 0xFF, (gen >> 8) & 0xFF]))
    return md5.digest()[:min(len(file_key) + 5, 16)]


def encrypt_objects(objects: list[bytes]) -> tuple[list[bytes], bytes]:
    """RC4-encrypt every stream payload in `objects` with its per-object key and
    append the /Encrypt dictionary as the last object.

    Only stream DATA is encrypted; the fixtures contain no literal strings
    outside the OutputIntent, and those are left as-is deliberately -- MuPDF
    decrypts strings with the same handler, so an unencrypted string would be
    decoded into noise and could confuse a reader of the fixture.  They are
    therefore removed from the encrypted variants instead (see build_pdfa()).
    """
    o_value = _owner_value()
    file_key = _file_key(o_value)
    u_value = _user_value(file_key)

    out: list[bytes] = []
    for num, body in enumerate(objects, start=1):
        marker = b"\nstream\n"
        at = body.find(marker)
        if at < 0:
            out.append(body)
            continue
        end = body.rfind(b"\nendstream")
        payload = body[at + len(marker):end]
        enc = rc4(_object_key(file_key, num, 0), payload)
        head = body[:at]
        # /Length must describe the ENCRYPTED bytes actually on disk.
        old_len = b"/Length " + str(len(payload)).encode()
        new_len = b"/Length " + str(len(enc)).encode()
        assert head.count(old_len) == 1, head
        head = head.replace(old_len, new_len)
        out.append(head + marker + enc + b"\nendstream")

    encrypt_dict = (
        b"<</Filter/Standard/V 2/R 3/Length " + str(ENC_KEY_BYTES * 8).encode()
        + b"/P " + str(ENC_PERMS).encode()
        + b"/O<" + o_value.hex().encode() + b">"
        + b"/U<" + u_value.hex().encode() + b">>>"
    )
    out.append(encrypt_dict)
    return out, b"/Encrypt " + str(len(out)).encode() + b" 0 R"


# ---------------------------------------------------------------------------
# Object-stream variant (PDF/A-1 clause 6.1.7)
# ---------------------------------------------------------------------------

def assemble_with_object_streams(objects: list[bytes]) -> bytes:
    """Re-assemble `objects` so that every non-stream object lives inside an
    /ObjStm and the file is indexed by a cross-reference STREAM.

    That is the only way to make `ProhibitedFeatureScanner::hasObjectStreams`
    true: it walks the xref for entries of type 'o'.
    """
    n = len(objects)
    objstm_num = n + 1
    xrefstm_num = n + 2

    compressed: list[int] = []      # 1-based object numbers going into the ObjStm
    uncompressed: list[int] = []
    for num, body in enumerate(objects, start=1):
        (uncompressed if b"\nstream\n" in body else compressed).append(num)

    # Build the ObjStm payload: a pairs header, then the object bodies.
    pairs = bytearray()
    bodies = bytearray()
    for num in compressed:
        pairs += str(num).encode() + b" " + str(len(bodies)).encode() + b" "
        bodies += objects[num - 1] + b"\n"
    first = len(pairs)
    objstm_payload = bytes(pairs) + bytes(bodies)
    objstm_deflated = zlib.compress(objstm_payload, 9)

    out = bytearray(HEADER)
    offsets: dict[int, int] = {}
    for num in uncompressed:
        offsets[num] = len(out)
        out += str(num).encode() + b" 0 obj\n" + objects[num - 1] + b"\nendobj\n"

    offsets[objstm_num] = len(out)
    out += (
        str(objstm_num).encode() + b" 0 obj\n"
        b"<</Type/ObjStm/N " + str(len(compressed)).encode()
        + b"/First " + str(first).encode()
        + b"/Filter/FlateDecode/Length " + str(len(objstm_deflated)).encode()
        + b">>\nstream\n" + objstm_deflated + b"\nendstream\nendobj\n"
    )

    xref_at = len(out)
    size = xrefstm_num + 1
    # W = [1 4 2]
    rows = bytearray()
    rows += bytes([0]) + struct.pack(">I", 0) + struct.pack(">H", 0xFFFF)
    for num in range(1, size):
        if num in offsets:
            rows += bytes([1]) + struct.pack(">I", offsets[num]) + struct.pack(">H", 0)
        elif num in compressed:
            idx = compressed.index(num)
            rows += bytes([2]) + struct.pack(">I", objstm_num) + struct.pack(">H", idx)
        else:   # the xref stream itself
            rows += bytes([1]) + struct.pack(">I", xref_at) + struct.pack(">H", 0)
    rows_deflated = zlib.compress(bytes(rows), 9)

    idhex = DOC_ID.hex().encode()
    out += (
        str(xrefstm_num).encode() + b" 0 obj\n"
        b"<</Type/XRef/Size " + str(size).encode()
        + b"/W[1 4 2]/Root 1 0 R"
        + b"/ID[<" + idhex + b"><" + idhex + b">]"
        + b"/Filter/FlateDecode/Length " + str(len(rows_deflated)).encode()
        + b">>\nstream\n" + rows_deflated + b"\nendstream\nendobj\n"
        b"startxref\n" + str(xref_at).encode() + b"\n%%EOF\n"
    )
    return bytes(out)


# ---------------------------------------------------------------------------
# The fixtures
# ---------------------------------------------------------------------------

# Each entry: (relative path, ISO clause it violates or "" for a control,
#              validation level, one-line statement of the SINGLE delta)
Fixture = tuple[str, str, str, str, bytes]


def build_pdfa() -> list[Fixture]:
    out: list[Fixture] = []

    def clean(part: str, conf: str, **kw) -> list[bytes]:
        return base_objects(part=part, conformance=conf, **kw)

    # --- controls: the validator must accept these with ZERO errors ---------
    out.append(("pdfa/pdfa_1b_control.pdf", "", "1b",
                "control -- nothing wrong; every negative below is this file "
                "plus exactly one defect",
                assemble(clean("1", "B"))))
    out.append(("pdfa/pdfa_2u_control.pdf", "", "2u",
                "control for the ToUnicode clause -- part 2 conformance U, "
                "every font carries /ToUnicode",
                assemble(clean("2", "U"))))
    out.append(("pdfa/pdfa_2a_control.pdf", "", "2a",
                "control for the tagging clause -- part 2 conformance A, "
                "/MarkInfo /Marked true plus a /StructTreeRoot",
                assemble(clean("2", "A", tagged=True))))

    # --- 6.7.11  XMP PDF/A identification -----------------------------------
    out.append(("pdfa/pdfa_6_7_11_no_xmp_identification.pdf", "6.7.11", "1b",
                "/Catalog /Metadata removed -- no pdfaid:part/conformance",
                assemble(clean("1", "B", with_xmp=False))))

    # --- 6.2.2  OutputIntent -------------------------------------------------
    out.append(("pdfa/pdfa_6_2_2_no_output_intent.pdf", "6.2.2", "1b",
                "/Catalog /OutputIntents removed",
                assemble(clean("1", "B", with_output_intent=False))))

    # --- 6.3.3  font embedding ----------------------------------------------
    out.append(("pdfa/pdfa_6_3_3_font_not_embedded.pdf", "6.3.3", "1b",
                "/FontDescriptor /FontFile2 removed -- font referenced by name",
                assemble(clean("1", "B", embed_font=False))))

    # --- 6.3.8  ToUnicode (only required at conformance U / A) --------------
    out.append(("pdfa/pdfa_6_3_8_no_tounicode.pdf", "6.3.8", "2u",
                "/Font /ToUnicode removed from the 2u control",
                assemble(clean("2", "U", with_tounicode=False))))

    # --- 6.1.3  encryption ---------------------------------------------------
    enc_objs, enc_trailer = encrypt_objects(clean("1", "B", with_output_intent=False))
    out.append(("pdfa/pdfa_6_1_3_encrypted.pdf", "6.1.3", "1b",
                "RC4-128 (/V 2 /R 3) standard security handler with an empty "
                "user password; /OutputIntents dropped because its literal "
                "strings would otherwise be decrypted into noise",
                assemble(enc_objs, trailer_extra=enc_trailer)))

    # --- 6.6.1  JavaScript ---------------------------------------------------
    # The untagged base is 9 objects, so the two appended here are 10 and 11.
    js_objs = clean("1", "B", catalog_extra=b"/Names<</JavaScript 10 0 R>>")
    assert len(js_objs) == 9, len(js_objs)
    js_objs.append(b"<</Names[(PDFEConformance) 11 0 R]>>")
    js_objs.append(b"<</S/JavaScript/JS(app.alert\\(\"pdfe conformance fixture\"\\);)>>")
    out.append(("pdfa/pdfa_6_6_1_javascript.pdf", "6.6.1", "1b",
                "/Catalog /Names /JavaScript name tree added",
                assemble(js_objs)))

    # --- 6.6.3  external references (Launch/Sound/Movie/GoToR) ---------------
    launch_objs = clean("1", "B", page_extra=b"/Annots[10 0 R]")
    assert len(launch_objs) == 9, len(launch_objs)
    launch_objs.append(
        b"<</Type/Annot/Subtype/Link/Rect[72 700 300 730]/Border[0 0 0]"
        b"/A<</S/Launch/F(pdfe-conformance-fixture.exe)>>>>")
    out.append(("pdfa/pdfa_6_6_3_launch_action.pdf", "6.6.3", "1b",
                "a /Link annotation whose action is /S /Launch",
                assemble(launch_objs)))

    # --- 6.4  transparency (prohibited in PDF/A-1 only) ---------------------
    out.append(("pdfa/pdfa_6_4_transparency_group.pdf", "6.4", "1b",
                "page /Group <</S /Transparency>> added",
                assemble(clean("1", "B",
                               page_extra=b"/Group<</Type/Group/S/Transparency"
                                          b"/CS/DeviceRGB>>"))))

    # --- 6.1.7  object streams (prohibited in PDF/A-1 only) -----------------
    out.append(("pdfa/pdfa_6_1_7_object_stream.pdf", "6.1.7", "1b",
                "identical objects, re-indexed through an /ObjStm and a "
                "cross-reference STREAM instead of an xref table",
                assemble_with_object_streams(clean("1", "B"))))

    # --- 6.8  tagging (required at conformance A) ---------------------------
    out.append(("pdfa/pdfa_6_8_untagged.pdf", "6.8", "2a",
                "/MarkInfo and /StructTreeRoot removed from the 2a control",
                assemble(clean("2", "A", tagged=False))))

    return out


def build_pdfua() -> list[Fixture]:
    out: list[Fixture] = []

    def ua_objects(*, with_struct: bool = True, with_lang: bool = True,
                   figure_alt: bytes | None = b"A single grey square") -> list[bytes]:
        catalog_extra = b""
        if with_lang:
            catalog_extra += b"/Lang(en-US)"
        objs = base_objects(part="2", conformance="A", tagged=False,
                            catalog_extra=catalog_extra, ua_part="1")
        if not with_struct:
            return objs
        # 10 StructTreeRoot, 11 Document StructElem, 12 Figure StructElem
        objs[0] = objs[0][:-2] + b"/MarkInfo<</Marked true>>/StructTreeRoot 10 0 R>>"
        objs.append(b"<</Type/StructTreeRoot/K[11 0 R]>>")
        objs.append(b"<</Type/StructElem/S/Document/P 10 0 R/K[12 0 R]>>")
        fig = b"<</Type/StructElem/S/Figure/P 11 0 R/Pg 3 0 R/K 0"
        if figure_alt is not None:
            fig += b"/Alt(" + figure_alt + b")"
        fig += b">>"
        objs.append(fig)
        return objs

    out.append(("pdfua/pdfua_control.pdf", "", "ua1",
                "control -- structure tree, /Lang, and a /Figure carrying /Alt",
                assemble(ua_objects())))

    out.append(("pdfua/pdfua_7_1_no_structure_tree.pdf", "7.1", "ua1",
                "/Catalog /StructTreeRoot removed",
                assemble(ua_objects(with_struct=False))))

    out.append(("pdfua/pdfua_7_2_no_document_language.pdf", "7.2", "ua1",
                "/Catalog /Lang removed",
                assemble(ua_objects(with_lang=False))))

    out.append(("pdfua/pdfua_7_3_figure_without_alt.pdf", "7.3", "ua1",
                "the /Figure structure element's /Alt removed (and no "
                "/ActualText substituted -- either would satisfy the clause)",
                assemble(ua_objects(figure_alt=None))))

    enc_objs, enc_trailer = encrypt_objects(ua_objects())
    out.append(("pdfua/pdfua_7_16_encrypted.pdf", "7.16", "ua1",
                "RC4-128 standard security handler over the control document",
                assemble(enc_objs, trailer_extra=enc_trailer)))

    return out


# ---------------------------------------------------------------------------
# Driver
# ---------------------------------------------------------------------------

MANIFEST_NAME = "manifest.json"


def build_all() -> list[Fixture]:
    return build_pdfa() + build_pdfua()


def manifest_for(fixtures: list[Fixture]) -> str:
    entries = []
    for rel, clause, level, delta, data in fixtures:
        entries.append({
            "path": rel,
            "kind": "control" if clause == "" else "clause-negative",
            "clause": clause,
            "validate_at": level,
            "single_delta_from_control": delta,
            "size": len(data),
            "sha256": hashlib.sha256(data).hexdigest(),
        })
    doc = {
        "_what": "Locally-authored PDF/A + PDF/UA clause-conformance corpus.",
        "_why_not_downloaded": (
            "The Isartor suite is not redistributable and the veraPDF corpus "
            "is a ~2,900-file network download; this project's fixtures must "
            "be committed and bounded. See gen_conformance_corpus.py for why a "
            "locally-authored fixture is not a self-consistent oracle here."
        ),
        "generator": "tests/fixtures/gen_conformance_corpus.py",
        "deterministic": True,
        "exercised_by": [
            "tests/test_pdfa_isartor_corpus.cpp",
            "tests/test_pdfua_clause_coverage.cpp",
            "tests/test_conformance_corpus_sampling.cpp",
        ],
        "fixtures": entries,
    }
    return json.dumps(doc, indent=2, ensure_ascii=False) + "\n"


def main() -> int:
    ap = argparse.ArgumentParser()
    ap.add_argument("--check", action="store_true",
                    help="verify the committed files match this generator; "
                         "write nothing")
    args = ap.parse_args()

    fixtures = build_all()
    manifest = manifest_for(fixtures)

    if args.check:
        bad = 0
        for rel, _clause, _level, _delta, data in fixtures:
            p = OUT_DIR / rel
            if not p.exists():
                print(f"MISSING {rel}")
                bad += 1
            elif p.read_bytes() != data:
                print(f"DRIFTED {rel}")
                bad += 1
        mp = OUT_DIR / MANIFEST_NAME
        if not mp.exists() or mp.read_text(encoding="utf-8") != manifest:
            print(f"DRIFTED {MANIFEST_NAME}")
            bad += 1
        print(f"gen_conformance_corpus --check: "
              f"{len(fixtures)} fixture(s), {bad} mismatch(es)")
        return 1 if bad else 0

    written = 0
    for rel, _clause, _level, _delta, data in fixtures:
        p = OUT_DIR / rel
        p.parent.mkdir(parents=True, exist_ok=True)
        if not p.exists() or p.read_bytes() != data:
            p.write_bytes(data)
            written += 1
    mp = OUT_DIR / MANIFEST_NAME
    if not mp.exists() or mp.read_text(encoding="utf-8") != manifest:
        mp.write_text(manifest, encoding="utf-8")
        written += 1
    print(f"gen_conformance_corpus: {len(fixtures)} fixture(s), "
          f"{written} written/updated -> {OUT_DIR}")
    return 0


if __name__ == "__main__":
    sys.exit(main())
